class BoundedBlockingQueue:
    def __init__(self, capacity):
        self.capacity = capacity
        self.queue = []                                                    # NOT thread-safe: two threads could corrupt this simultaneously

    def enqueue(self, element):
        while len(self.queue) >= self.capacity:                           # busy-wait: repeatedly re-check, wasting CPU the whole time
            pass
        self.queue.append(element)

    def dequeue(self):
        while len(self.queue) == 0:                                       # busy-wait here too: no actual thread coordination at all
            pass
        return self.queue.pop(0)

    def size(self):
        return len(self.queue)


if __name__ == "__main__":
    bq = BoundedBlockingQueue(2)
    bq.enqueue(1)
    print(bq.size())
    bq.enqueue(2)
    print(bq.size())
    print(bq.dequeue())
    print(bq.dequeue())

