import java.util.*;

public class Main {
    class BoundedBlockingQueue {
        int capacity;
        List<Integer> queue = new ArrayList<>();                                    // NOT thread-safe: two threads could corrupt this simultaneously

        BoundedBlockingQueue(int capacity) { this.capacity = capacity; }

        void enqueue(int element) throws InterruptedException {
            while (queue.size() >= capacity) { }                                        // busy-wait: repeatedly re-check, wasting CPU the whole time
            queue.add(element);
        }

        int dequeue() throws InterruptedException {
            while (queue.isEmpty()) { }                                                 // busy-wait here too: no actual thread coordination at all
            return queue.remove(0);
        }

        int size() {
            return queue.size();
        }
    }

    public static void main(String[] args) {
        BoundedBlockingQueue bq = new BoundedBlockingQueue(2);
        bq.enqueue(1);
        System.out.println(bq.size());
        bq.enqueue(2);
        System.out.println(bq.size());
        System.out.println(bq.dequeue());
        System.out.println(bq.dequeue());
    }
}

