using namespace std;

class BoundedBlockingQueue {
public:
    int capacity;
    vector<int> queue;                                                                // NOT thread-safe: two threads could corrupt this simultaneously

    BoundedBlockingQueue(int capacity) : capacity(capacity) {}

    void enqueue(int element) {
        while ((int)queue.size() >= capacity) { }                                        // busy-wait: repeatedly re-check, wasting CPU the whole time
        queue.push_back(element);
    }

    int dequeue() {
        while (queue.empty()) { }                                                        // busy-wait here too: no actual thread coordination at all
        int front = queue.front();
        queue.erase(queue.begin());
        return front;
    }

    int size() {
        return queue.size();
    }
};

int main() {
    BoundedBlockingQueue bq(2);
    bq.enqueue(1);
    cout << bq.size() << endl;
    bq.enqueue(2);
    cout << bq.size() << endl;
    cout << bq.dequeue() << endl;
    cout << bq.dequeue() << endl;
    return 0;
}

