import java.util.*;

public class Main {
    class BoundedBlockingQueue {
        int capacity;
        Deque<Integer> queue = new ArrayDeque<>();
        final Object lock = new Object();                                                  // a single monitor lock guards all access

        BoundedBlockingQueue(int capacity) { this.capacity = capacity; }

        void enqueue(int element) throws InterruptedException {
            synchronized (lock) {
                while (queue.size() >= capacity) {
                    lock.wait();                                                                // sleeps efficiently, no CPU wasted, until notified
                }
                queue.addLast(element);
                lock.notifyAll();                                                              // wake up any thread waiting to dequeue (or enqueue)
            }
        }

        int dequeue() throws InterruptedException {
            synchronized (lock) {
                while (queue.isEmpty()) {
                    lock.wait();                                                                // sleeps efficiently until notified
                }
                int val = queue.pollFirst();
                lock.notifyAll();                                                              // wake up any thread waiting to enqueue (or dequeue)
                return val;
            }
        }

        int size() {
            synchronized (lock) {
                return queue.size();
            }
        }
    }

    public static void main(String[] args) {
        BoundedBlockingQueue bq = new BoundedBlockingQueue(2);
        bq.enqueue(1);
        System.out.println(bq.size());
        bq.enqueue(2);
        System.out.println(bq.size());
        System.out.println(bq.dequeue());
        System.out.println(bq.dequeue());
    }
}

