#include <bits/stdc++.h>
using namespace std;

class BoundedBlockingQueue {
public:
    int capacity;
    deque<int> queue;
    mutex mtx;
    condition_variable notFull, notEmpty;                                                  // separate condition variables for each waiting reason

    BoundedBlockingQueue(int capacity) : capacity(capacity) {}

    void enqueue(int element) {
        unique_lock<mutex> lock(mtx);
        notFull.wait(lock, [this] { return (int)queue.size() < capacity; });                    // sleeps efficiently until the predicate holds
        queue.push_back(element);
        notEmpty.notify_one();                                                                     // wake up one thread waiting to dequeue
    }

    int dequeue() {
        unique_lock<mutex> lock(mtx);
        notEmpty.wait(lock, [this] { return !queue.empty(); });                                     // sleeps efficiently until the predicate holds
        int val = queue.front();
        queue.pop_front();
        notFull.notify_one();                                                                          // wake up one thread waiting to enqueue
        return val;
    }

    int size() {
        unique_lock<mutex> lock(mtx);
        return queue.size();
    }
};

int main() {
    BoundedBlockingQueue bq(2);
    bq.enqueue(1);
    cout << bq.size() << endl;
    bq.enqueue(2);
    cout << bq.size() << endl;
    cout << bq.dequeue() << endl;
    cout << bq.dequeue() << endl;
    return 0;
}
